/* Compat UI legacy: titulo / subcategorias / items (+ subsubcategorias / familias) */
function _ingproBuildCategoriasFromTaxonomia(root) {
  const cats = Array.isArray(root) ? root : [];
  return cats.map((cat) => {
    const subs = cat.subcategorias || cat.subcategories || [];
    return {
      titulo: cat.name || '',
      code: cat.code || '',
      path: cat.path || cat.name || '',
      subcategorias: subs.map((sub) => {
        const subsubs = sub.subsubcategorias || sub.subsubcategories || [];
        const subsubcategorias = subsubs.map((ss) => {
          let familiasRaw = ss.familias || ss.families || [];
          // Sub-sub sin familias (ej. G206 Crimping tools): tratarla como hoja navegable
          if ((!familiasRaw || !familiasRaw.length) && ss.code) {
            familiasRaw = [{
              code: ss.code,
              name: ss.name || '',
              path: ss.path || '',
              productos: [],
              products: [],
            }];
          }
          const familias = [];
          const items = [];
          for (const f of familiasRaw) {
            const name = f && f.name ? String(f.name) : '';
            const code = f && f.code ? String(f.code) : '';
            const label = code ? (name + ' - ' + code) : name;
            if (label) items.push(label);
            familias.push({
              code: code,
              name: name,
              path: f.path || ss.path || '',
              label: label,
            });
            // Productos anidados bajo familia (ej. G205a- Manual saws)
            const nested = f.productos || f.products || [];
            for (const pr of nested) {
              const pn = pr && pr.name ? String(pr.name) : '';
              const pc = pr && pr.code ? String(pr.code) : '';
              const pl = pc ? (pn + ' - ' + pc) : pn;
              if (!pl) continue;
              items.push(pl);
              familias.push({
                code: pc,
                name: pn,
                path: pr.path || f.path || ss.path || '',
                label: pl,
              });
            }
          }
          return {
            code: ss.code || '',
            subtitulo: ss.name || '',
            name: ss.name || '',
            path: ss.path || '',
            items,
            familias,
          };
        });
        const items = subsubcategorias.reduce((acc, ss) => acc.concat(ss.items || []), []);
        return {
          code: sub.code || '',
          subtitulo: sub.name || '',
          name: sub.name || '',
          path: sub.path || '',
          items,
          subsubcategorias,
        };
      }),
    };
  });
}

const _taxRoot = (typeof taxonomia !== 'undefined')
  ? taxonomia
  : ((typeof taxonomy !== 'undefined') ? taxonomy : []);
const categorias = _ingproBuildCategoriasFromTaxonomia(_taxRoot);
try {
  window.taxonomia = _taxRoot;
  window.taxonomy = _taxRoot;
  window.categorias = categorias;
} catch (_) {}
